from jinja2 import Template


def render_message(recipient: str, body: str) -> str:
    """Render a message template for the given recipient in NotifyHub layout."""
    template = Template(body)
    rendered_body = template.render(recipient=recipient)
    return f"""To: {recipient}

{rendered_body}

Sent with NotifyHub"""
